#ifndef STD_MSGS__MSG__FLOAT64_HPP_
#define STD_MSGS__MSG__FLOAT64_HPP_

// Auto-generated ROS 2-style compatibility header for ROS 1.
// Provides: std_msgs::msg::Float64 as a using-alias for the ROS 1
// type std_msgs::Float64. Logic-layer code that declares shared_ptr
// arguments as std::shared_ptr<const T> works on both builds; on ROS 1
// the IF layer converts boost::shared_ptr -> std::shared_ptr via
// sq_ros1_compat::to_std() (no deep copy).

#include "std_msgs/Float64.h"

namespace std_msgs {
namespace msg {
using Float64 = ::std_msgs::Float64;
}  // namespace msg
}  // namespace std_msgs

#endif  // STD_MSGS__MSG__FLOAT64_HPP_
